import { test, expect } from '@playwright/test';

test.describe('Error Toast Notification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display error toast notification when action fails', async ({ page }) => {
    // Intercept the API call
    await page.route('**/api/user/actions/save', (route) => {
      route.abort('failed');
    });

    // Click the button to trigger the action
    const saveButton = page.getByRole('button', { name: /save changes/i });
    await saveButton.click();

    // Wait for the toast to appear
    const toast = page.getByRole('alert');
    await expect(toast).toBeVisible();

    // Verify the toast contains the error message
    await expect(toast).toContainText('Failed to save changes');

    // Verify the toast has a dismiss button
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();

    // Verify the toast has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify the toast has a timestamp
    const timestamp = page.getByText(/at \d{2}:\d{2}:\d{2}/i);
    await expect(timestamp).toBeVisible();

    // Verify the toast has a success icon
    const successIcon = page.getByRole('img', { name: /success/i });
    await expect(successIcon).toBeVisible();

    // Verify the toast has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify the toast is dismissed when clicked
    await dismissButton.click();
    await expect(toast).not.toBeVisible();
  });

  test('should not display error toast when action succeeds', async ({ page }) => {
    // Mock successful API response
    await page.route('**/api/user/actions/save', (route) => {
      route.continue();
    });

    // Click the button to trigger the action
    const saveButton = page.getByRole('button', { name: /save changes/i });
    await saveButton.click();

    // Wait for the toast to appear
    const toast = page.getByRole('alert');
    await expect(toast).not.toBeVisible();

    // Verify no toast is displayed
    const noToast = page.getByText(/no error/i);
    await expect(noToast).toBeVisible();

    // Verify the success message is displayed
    const successMessage = page.getByText(/saved successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify the success icon is present
    const successIcon = page.getByRole('img', { name: /success/i });
    await expect(successIcon).toBeVisible();

    // Verify the toast is dismissed when clicked
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();
    await dismissButton.click();
    await expect(toast).not.toBeVisible();
  });
});
